import pandas as pd

def solve(data):
     df = pd.DataFrame(data['rows'])
     df['date'] = pd.to_datetime(df['date'])
     monthly = df.set_index('date')['amount'].resample('MS').sum()
     return {date.strftime('%Y-%m'):float(value) for date,value in monthly.items()}
